from ..models.oxygen import OxygenStock, OxygenCenter, OxygenRequest, OxygenAlert
from ..models.hospital import Hospital
from ..schemas.oxygen import (
    OxygenStockResponse, OxygenStockUpdateRequest,
    OxygenCenterResponse, OxygenRequestCreate, OxygenRequestResponse,
    OxygenAlertResponse, OxygenDashboardResponse,
)
from ..core.exceptions import NotFoundException, BadRequestException
from ..utils.helpers import build_pagination_meta, generate_request_number


class OxygenServiceLayer:
    def __init__(self, db: Session):
        self.db = db

    def get_all_stocks(self, page: int = 1, size: int = 20) -> dict:
        query = self.db.query(OxygenStock)
        total = query.count()
        stocks = query.offset((page - 1) * size).limit(size).all()
        return {
            "items": [OxygenStockResponse.model_validate(s) for s in stocks],
            **build_pagination_meta(total, page, size),
        }

    def get_hospital_stock(self, hospital_id: str) -> OxygenStockResponse:
        stock = self.db.query(OxygenStock).filter(OxygenStock.hospital_id == hospital_id).first()
        if not stock:
            raise NotFoundException("Oxygen stock not found for this hospital")
        return OxygenStockResponse.model_validate(stock)

    def update_stock(self, stock_id: str, data: OxygenStockUpdateRequest) -> OxygenStockResponse:
        stock = self.db.query(OxygenStock).filter(OxygenStock.id == stock_id).first()
        if not stock:
            raise NotFoundException("Oxygen stock record not found")
        update_fields = data.model_dump(exclude_unset=True)
        for field, value in update_fields.items():
            setattr(stock, field, value)
        # Auto-update status
        available = stock.available_cylinders or 0
        total = stock.total_cylinders or 1
        if available == 0:
            stock.status = "out-of-stock"
        elif available / total < 0.1:
            stock.status = "critical"
        elif available / total < 0.3:
            stock.status = "low"
        else:
            stock.status = "sufficient"
        self.db.commit()
        self.db.refresh(stock)
        return OxygenStockResponse.model_validate(stock)

    def get_nearby_centers(self, lat: float, lng: float, radius: float = 10, page: int = 1, size: int = 20) -> dict:
        query = self.db.query(OxygenCenter).filter(OxygenCenter.is_active == True)
        total = query.count()
        centers = query.offset((page - 1) * size).limit(size).all()
        return {
            "items": [OxygenCenterResponse.model_validate(c) for c in centers],
            **build_pagination_meta(total, page, size),
        }

    def create_request(self, user_id: str, data: OxygenRequestCreate) -> OxygenRequestResponse:
        request_number = generate_request_number("OXY")
        req = OxygenRequest(
            request_number=request_number,
            patient_name=data.patient_name,
            patient_age=data.patient_age,
            patient_condition=data.patient_condition,
            oxygen_type=data.oxygen_type,
            cylinders_needed=data.cylinders_needed,
            urgency=data.urgency,
            hospital_name=data.hospital_name,
            doctor_name=data.doctor_name,
            status="pending",
            delivery_address=data.delivery_address,
            latitude=data.latitude,
            longitude=data.longitude,
            contact_phone=data.contact_phone,
            contact_email=data.contact_email,
            requested_by=user_id,
            hospital_id=data.hospital_id,
            required_date=data.required_date,
        )
        self.db.add(req)
        self.db.commit()
        self.db.refresh(req)
        return OxygenRequestResponse.model_validate(req)

    def get_requests(self, user_id: Optional[str] = None, status: Optional[str] = None, page: int = 1, size: int = 20) -> dict:
        query = self.db.query(OxygenRequest)
        if user_id:
            query = query.filter(OxygenRequest.requested_by == user_id)
        if status:
            query = query.filter(OxygenRequest.status == status)
        query = query.order_by(OxygenRequest.created_at.desc())
        total = query.count()
        requests = query.offset((page - 1) * size).limit(size).all()
        return {
            "items": [OxygenRequestResponse.model_validate(r) for r in requests],
            **build_pagination_meta(total, page, size),
        }

    def update_request_status(self, request_id: str, status: str) -> OxygenRequestResponse:
        req = self.db.query(OxygenRequest).filter(OxygenRequest.id == request_id).first()
        if not req:
            raise NotFoundException("Oxygen request not found")
        valid = ["pending", "approved", "dispatched", "delivered", "cancelled"]
        if status not in valid:
            raise BadRequestException(f"Invalid status. Must be one of: {valid}")
        req.status = status
        if status == "delivered":
            req.delivery_date = date.today()
        self.db.commit()
        self.db.refresh(req)
        return OxygenRequestResponse.model_validate(req)

    def get_alerts(self, page: int = 1, size: int = 20) -> dict:
        query = self.db.query(OxygenAlert).order_by(OxygenAlert.created_at.desc())
        total = query.count()
        alerts = query.offset((page - 1) * size).limit(size).all()
        return {
            "items": [OxygenAlertResponse.model_validate(a) for a in alerts],
            **build_pagination_meta(total, page, size),
        }

    def get_dashboard(self) -> OxygenDashboardResponse:
        total_centers = self.db.query(OxygenCenter).filter(OxygenCenter.is_active == True).count()
        total_cylinders = self.db.query(func.sum(OxygenStock.total_cylinders)).scalar() or 0
        available = self.db.query(func.sum(OxygenStock.available_cylinders)).scalar() or 0
        critical = self.db.query(OxygenStock).filter(OxygenStock.status.in_(["critical", "out-of-stock"])).count()
        pending = self.db.query(OxygenRequest).filter(OxygenRequest.status == "pending").count()
        return OxygenDashboardResponse(
            total_centers=total_centers,
            total_cylinders=total_cylinders,
            available_cylinders=available,
            critical_alerts=critical,
            pending_requests=pending,
        )

from sqlalchemy.orm import Session
from typing import Optional, List
from datetime import datetime

from ..models.ai_assistant import AIConversation, AIMessage, AIVoiceSession
from ..schemas.ai_assistant import (
    AIChatRequest, AIMessageResponse,
    AIConversationResponse, AIVoiceSessionResponse,
)
from ..core.exceptions import NotFoundException
from ..utils.helpers import build_pagination_meta


class AIAssistantService:
    def __init__(self, db: Session):
        self.db = db

    def chat(self, user_id: str, data: AIChatRequest) -> AIMessageResponse:
        # Get or create conversation
        conversation = None
        if data.conversation_id:
            conversation = self.db.query(AIConversation).filter(
                AIConversation.id == data.conversation_id,
                AIConversation.user_id == user_id,
            ).first()
            if not conversation:
                raise NotFoundException("Conversation not found")

        if not conversation:
            conversation = AIConversation(
                user_id=user_id,
                title=data.message[:50] + "..." if len(data.message) > 50 else data.message,
                status="active",
            )
            self.db.add(conversation)
            self.db.flush()

        # Store user message
        user_msg = AIMessage(
            conversation_id=conversation.id,
            role="user",
            content=data.message,
            type="text",
        )
        self.db.add(user_msg)

        # Generate AI response (rule-based for now — no external API)
        ai_content, suggestions, emotion, confidence = self._generate_response(data.message)

        ai_msg = AIMessage(
            conversation_id=conversation.id,
            role="assistant",
            content=ai_content,
            type="text",
            emotion=emotion,
            confidence=confidence,
            suggestions=suggestions,
        )
        self.db.add(ai_msg)
        self.db.commit()
        self.db.refresh(ai_msg)

        return AIMessageResponse(
            id=ai_msg.id,
            conversation_id=conversation.id,
            role=ai_msg.role,
            content=ai_msg.content,
            type=ai_msg.type,
            emotion=ai_msg.emotion,
            confidence=float(ai_msg.confidence) if ai_msg.confidence else None,
            suggestions=ai_msg.suggestions,
            created_at=ai_msg.created_at,
        )

    def get_conversations(self, user_id: str, page: int = 1, size: int = 20) -> dict:
        query = self.db.query(AIConversation).filter(
            AIConversation.user_id == user_id,
            AIConversation.status != "deleted",
        ).order_by(AIConversation.created_at.desc())

        total = query.count()
        conversations = query.offset((page - 1) * size).limit(size).all()

        return {
            "items": [AIConversationResponse.model_validate(c) for c in conversations],
            **build_pagination_meta(total, page, size),
        }

    def get_conversation_messages(self, conversation_id: str, user_id: str, page: int = 1, size: int = 50) -> dict:
        conversation = self.db.query(AIConversation).filter(
            AIConversation.id == conversation_id,
            AIConversation.user_id == user_id,
        ).first()
        if not conversation:
            raise NotFoundException("Conversation not found")

        query = self.db.query(AIMessage).filter(
            AIMessage.conversation_id == conversation_id,
        ).order_by(AIMessage.created_at.asc())

        total = query.count()
        messages = query.offset((page - 1) * size).limit(size).all()

        return {
            "items": [AIMessageResponse.model_validate(m) for m in messages],
            **build_pagination_meta(total, page, size),
        }

    def create_voice_session(self, user_id: str) -> AIVoiceSessionResponse:
        session = AIVoiceSession(
            user_id=user_id,
            is_listening=True,
        )
        self.db.add(session)
        self.db.commit()
        self.db.refresh(session)
        return AIVoiceSessionResponse.model_validate(session)

    def _generate_response(self, message: str) -> tuple:
        msg_lower = message.lower()

        if any(w in msg_lower for w in ["emergency", "urgent", "help", "911", "sos"]):
            return (
                "This sounds urgent. If this is a medical emergency, please call your local emergency number (911) immediately. "
                "I can also help you find nearby hospitals or request an ambulance through our emergency system.",
                ["Find nearby hospitals", "Request ambulance", "Call emergency"],
                "concerned", 0.95
            )
        elif any(w in msg_lower for w in ["headache", "pain", "fever", "cough", "cold", "flu"]):
            return (
                "I understand you're experiencing symptoms. For proper diagnosis, please consult a healthcare professional. "
                "I can help you find a doctor or book an appointment. Can you share more details about when symptoms started?",
                ["Find a doctor", "Book appointment", "Check symptoms"],
                "concerned", 0.75
            )
        elif any(w in msg_lower for w in ["medicine", "drug", "prescription", "pharmacy"]):
            return (
                "I can help you with medicine-related queries. I can search for medicines, compare prices at pharmacies, "
                "or help you find a nearby pharmacy. What specifically would you like to know?",
                ["Search medicines", "Find pharmacy", "Compare prices"],
                "neutral", 0.70
            )
        elif any(w in msg_lower for w in ["appointment", "book", "schedule", "doctor"]):
            return (
                "I can help you find and book appointments with doctors. Would you like to search by specialty, "
                "name, or location?",
                ["Search doctors", "Book appointment", "View specialties"],
                "neutral", 0.80
            )
        else:
            return (
